<?php
declare(strict_types=1);
require dirname(__DIR__) . '/private/bootstrap.php';
require_public_site_online();
$s = settings();
$lotNum = filter_input(INPUT_GET, 'nr', FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]);
if ((int)($s['is_published'] ?? 0) !== 1 || !$lotNum) { http_response_code(404); exit('Kavel niet gevonden.'); }
$st = db()->prepare("SELECT * FROM lots WHERE lot_number=? AND status IN ('published','sold') LIMIT 1");
$st->execute([$lotNum]);
$lot = $st->fetch();
if (!$lot) { http_response_code(404); exit('Kavel niet gevonden.'); }
require_once dirname(__DIR__) . '/private/visitor_stats.php';
track_catalog_view((int)$lot['id']);
$imagesSt = db()->prepare('SELECT path FROM lot_images WHERE lot_id=? ORDER BY sort_order, id');
$imagesSt->execute([(int)$lot['id']]);
$images = $imagesSt->fetchAll(PDO::FETCH_COLUMN);
$prevSt = db()->prepare("SELECT lot_number FROM lots WHERE status IN ('published','sold') AND lot_number < ? ORDER BY lot_number DESC LIMIT 1");
$prevSt->execute([$lotNum]); $prev = $prevSt->fetchColumn();
$nextSt = db()->prepare("SELECT lot_number FROM lots WHERE status IN ('published','sold') AND lot_number > ? ORDER BY lot_number ASC LIMIT 1");
$nextSt->execute([$lotNum]); $next = $nextSt->fetchColumn();
$cover = $images[0] ?? 'assets/placeholder.svg';
?><!doctype html><html lang="nl"><head><link rel="icon" type="image/png" href="/favicon.png?v=3"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=e($lot['title'] . ' — ' . $lot['subtitle'])?>"><meta property="og:title" content="<?=e('Kavel ' . $lotNum . ' — ' . $lot['title'])?>"><meta property="og:image" content="<?=e(url($cover))?>"><title><?=e($lot['title'])?> | Kavel <?=e((string)$lotNum)?></title><link rel="stylesheet" href="<?=e(url('assets/catalogus.css'))?>?v=187"></head>
<body><header class="site-header"><div class="shell header-inner"><a href="<?=e(url('index.php'))?>" class="brand"><span class="brand-mark">41</span><span class="brand-name">41 LOKEREN<small>KUNST · LIFESTYLE · VINTAGE</small></span></a><nav class="header-nav"><a href="<?=e(url('index.php'))?>#catalogus">← Alle kavels</a><a href="<?=e(url('index.php'))?>#informatie">Praktisch</a><a id="favoriteLink" class="header-favorites" href="<?=e(url('index.php',['favorieten'=>1]))?>">♡ <span id="favoriteCount">0</span></a></nav></div></header>
<main class="detail-page shell"><a class="back-link" href="<?=e(url('index.php'))?>#catalogus">← Terug naar de catalogus</a><div class="detail-page-grid"><div class="detail-gallery"><div class="main-photo"><img id="mainPhoto" src="<?=e(url($cover))?>" alt="<?=e($lot['title'])?>"></div><?php if(count($images)>1): ?><div class="thumb-row"><?php foreach($images as $idx=>$image): ?><button type="button" class="thumb gallery-thumb" aria-label="Toon foto <?=($idx+1)?>" aria-pressed="<?=$idx===0?'true':'false'?>" data-photo="<?=e(url($image))?>"><img loading="lazy" src="<?=e(url($image))?>" alt="Detailfoto <?=($idx+1)?>"></button><?php endforeach; ?></div><?php endif; ?></div><div class="detail-copy"><?php if ($lot['status'] === 'sold'): ?><span class="lot-sold-badge detail-sold-badge">Verkocht</span><?php endif; ?><p class="eyebrow detail-category">KAVEL <?=e(str_pad((string)$lotNum,3,'0',STR_PAD_LEFT))?> · <?=e($lot['category'])?></p><h1><?=e($lot['title'])?></h1><?php if($lot['subtitle']): ?><p class="detail-subtitle"><?=e($lot['subtitle'])?></p><?php endif; ?><?php if($lot['description']): ?><div class="detail-description"><?=nl2br(e($lot['description']))?></div><?php endif; ?><?php if($lot['details']): ?><div class="detail-specs"><?=nl2br(e($lot['details']))?></div><?php endif; ?><div class="detail-estimate"><span>MARKTPRIJS / MARKTPRIJS</span><strong><?=e(estimate($lot))?></strong></div><div class="detail-actions"><button id="detailFavorite" class="btn btn-dark" data-favorite="<?=$lotNum?>" type="button" aria-pressed="false">♡ Bewaar als favoriet</button><button id="shareLot" class="btn btn-outline" type="button">↗ Deel dit kavel</button></div><div class="detail-notice">Bieden gebeurt uitsluitend tijdens de fysieke veiling. Deze website aanvaardt geen online biedingen.</div></div></div><nav class="detail-bottom-nav"><?php if($prev): ?><a href="<?=e(url('kavel.php',['nr'=>(int)$prev]))?>">← Vorig kavel</a><?php else: ?><span></span><?php endif; ?><a href="<?=e(url('index.php'))?>#catalogus">Alle kavels</a><?php if($next): ?><a href="<?=e(url('kavel.php',['nr'=>(int)$next]))?>">Volgend kavel →</a><?php else: ?><span></span><?php endif; ?></nav></main><footer class="footer"><div class="shell footer-inner"><span class="footer-brand"><strong>41 LOKEREN · VEILING 2027</strong></span><p><?=e($s['title'])?></p><a href="<?=e(url('privacy.php'))?>">Privacy</a><a href="<?=e(url('pecharko.php'))?>">Designed by Pecharko</a><a href="<?=e(url('index.php'))?>">Terug naar catalogus</a></div></footer><script src="<?=e(url('assets/catalogus.js'))?>" defer></script></body></html>
